changeSet.sql:
DO $$
BEGIN
    IF to_regclass('ui_table_view') IS NULL
       OR NOT EXISTS (SELECT 1 FROM information_schema.columns
                      WHERE table_name = 'ui_table_view' AND column_name = 'kind') THEN
        RETURN;
    END IF;
    CREATE UNIQUE INDEX IF NOT EXISTS ux_ui_table_view_default
        ON ui_table_view (fk_institution, resource_type, COALESCE(fk_project, 0), COALESCE(type_id, 0))
        WHERE kind = 'DEFAULT';
END
$$;
